def show_help():
    """Show command help banner"""
    help_text = '''
    ═══════════════════════════════════════════════════════════════
      MYSŌNINJA — ARSENAL COMMANDS
    ═══════════════════════════════════════════════════════════════
    
      🎯 TARGETS        — add, list, manage targets
      💀 PAYLOADS       — generate reverse shells (all platforms)
      📡 C2             — start/stop command & control listener
      🔍 RECON          — DNS, port, subdomain enumeration
      🎣 PHISHING       — generate phishing campaigns
      ⚡ EXPLOITS       — run exploits (EternalBlue, etc.)
      🏴 PERSISTENCE    — registry, scheduled tasks, services
      📶 WIRELESS       — WiFi scanning, deauth, handshake capture
      🖥️  TERMINAL       — execute system commands directly
    
    ═══════════════════════════════════════════════════════════════
    '''
    print(help_text)

